require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$editing=$id>0;
$base=['name'=>'','category'=>'Food & Cafes','location'=>'','city'=>'','address'=>'','phone'=>'','whatsapp'=>'','email'=>'','website'=>'','description'=>'','tags'=>'','price_range'=>'','opening_hours'=>'','latitude'=>'','longitude'=>'','image_url'=>'','meta_title'=>'','meta_description'=>'','status'=>'draft','featured'=>0,'sponsored'=>0,'verified'=>0,'image_path'=>'','is_demo'=>0];$l=$base;
if($editing){$s=db()->prepare('SELECT * FROM listings WHERE id=:id');$s->execute([':id'=>$id]);$found=$s->fetch();if(!$found){flash('error','Listing not found.');redirect(app_path('admin/listings.php'));}$l=array_merge($base,$found);}
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();foreach(['name','category','location','city','address','phone','whatsapp','email','website','description','tags','price_range','opening_hours','image_url','meta_title','meta_description','status'] as $k)$l[$k]=trim((string)($_POST[$k]??''));$lat=trim((string)($_POST['latitude']??''));$lng=trim((string)($_POST['longitude']??''));$l['latitude']=$lat;$l['longitude']=$lng;$l['featured']=isset($_POST['featured'])?1:0;$l['sponsored']=isset($_POST['sponsored'])?1:0;$l['verified']=isset($_POST['verified'])?1:0;
 if($l['name']===''||text_len($l['name'])>140)$errors[]='Enter a listing name (max 140 characters).';if(!in_array($l['category'],categories(),true))$errors[]='Choose a valid category.';if($l['location']==='')$errors[]='Enter a neighbourhood or area.';if(text_len($l['description'])<30)$errors[]='Description must be at least 30 characters.';if($l['email']!==''&&!filter_var($l['email'],FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';$website=valid_http_url($l['website']);if($l['website']!==''&&!$website)$errors[]='Enter a valid website URL.';$imageUrl=valid_http_url($l['image_url']);if($l['image_url']!==''&&!$imageUrl)$errors[]='Enter a valid image URL.';$latitude=$lat===''?null:filter_var($lat,FILTER_VALIDATE_FLOAT);$longitude=$lng===''?null:filter_var($lng,FILTER_VALIDATE_FLOAT);if($lat!==''&&($latitude===false||$latitude < -90||$latitude>90))$errors[]='Latitude must be between -90 and 90.';if($lng!==''&&($longitude===false||$longitude < -180||$longitude>180))$errors[]='Longitude must be between -180 and 180.';if(($latitude===null)!==($longitude===null))$errors[]='Enter both latitude and longitude, or leave both blank.';if(!in_array($l['status'],['published','draft','pending'],true))$l['status']='draft';
 if(!$errors){try{$new=upload_listing_image($_FILES['image']??['error'=>UPLOAD_ERR_NO_FILE]);if($new){delete_uploaded_image($l['image_path']);$l['image_path']=$new;}}catch(Throwable $e){$errors[]=$e->getMessage();}}
 if(!$errors){$data=[':name'=>$l['name'],':slug'=>unique_slug($l['name'],$editing?$id:null),':cat'=>$l['category'],':loc'=>$l['location'],':city'=>$l['city'],':addr'=>$l['address'],':phone'=>$l['phone'],':wa'=>$l['whatsapp'],':email'=>$l['email'],':web'=>$website,':desc'=>$l['description'],':tags'=>$l['tags'],':price'=>$l['price_range'],':hours'=>$l['opening_hours'],':lat'=>$latitude,':lng'=>$longitude,':imgp'=>$l['image_path'],':imgu'=>$imageUrl,':mt'=>$l['meta_title'],':md'=>$l['meta_description'],':status'=>$l['status'],':featured'=>$l['featured'],':sponsored'=>$l['sponsored'],':verified'=>$l['verified']];
  if($editing){$data[':id']=$id;$sql='UPDATE listings SET name=:name,slug=:slug,category=:cat,location=:loc,city=:city,address=:addr,phone=:phone,whatsapp=:wa,email=:email,website=:web,description=:desc,tags=:tags,price_range=:price,opening_hours=:hours,latitude=:lat,longitude=:lng,image_path=:imgp,image_url=:imgu,meta_title=:mt,meta_description=:md,status=:status,featured=:featured,sponsored=:sponsored,verified=:verified,is_demo=0,updated_at=CURRENT_TIMESTAMP WHERE id=:id';}
  else{$sql='INSERT INTO listings(name,slug,category,location,city,address,phone,whatsapp,email,website,description,tags,price_range,opening_hours,latitude,longitude,image_path,image_url,meta_title,meta_description,status,featured,sponsored,verified,is_demo) VALUES(:name,:slug,:cat,:loc,:city,:addr,:phone,:wa,:email,:web,:desc,:tags,:price,:hours,:lat,:lng,:imgp,:imgu,:mt,:md,:status,:featured,:sponsored,:verified,0)';}
  db()->prepare($sql)->execute($data);flash('success',$editing?'Listing updated.':'Listing created.');redirect(app_path('admin/listings.php'));
 }
}
$adminTitle=$editing?'Edit listing':'Create listing';include __DIR__.'/_header.php';?>
